// Valuation readiness: reports which of the three BOV inputs a contact has
// (completed valuation questionnaire, Financials in a data room, Lease in a data room),
// plus the latest valuation record + state. Read-only; drives the dimmed "Generate
// Valuation" action on the contact page and the three-input generate gate.
// Resolve a single listing/deal from a listing key ('s_<screenId>' or 'd_<dealId>').
// Used to scope the seller-actions pipeline to ONE business when a seller has several.
function _dealFromListingKey(lk) {
  lk = String(lk || '').trim();
  if (!lk) return null;
  try {
    const deals = loadDeals();
    if (lk.slice(0, 2) === 's_') return deals.find(d => d.screenId === lk.slice(2)) || null;
    if (lk.slice(0, 2) === 'd_') return deals.find(d => d.id === lk.slice(2)) || null;
  } catch (e) {}
  return null;
}
app.get('/api/valuation-readiness', (req, res) => {
  try {
    const pid = String(req.query.personId || '').trim().slice(0, 48);
    const cid = String(req.query.companyId || '').trim().slice(0, 48);
    const hit = o => !!o && ((pid && (o.personId === pid || o.contactPersonId === pid)) || (cid && o.companyId === cid));
    // ---- Listing-scoped path: when a listingKey is supplied, resolve the state for THAT
    // one business only (its screening, its data room, a BOV tagged to it). Falls through
    // to the person/company aggregate when no listingKey (single-business — unchanged). ----
    const _lk = String(req.query.listingKey || '').trim().slice(0, 64);
    const _sd = _lk ? _dealFromListingKey(_lk) : null;
    if (_lk && _sd) {
      let scr = false, scrSkip = false, ivSkip = false;
      // A skip flag can be recorded under the listing key, the deal's s_<screenId> key, OR its
      // d_<id> key — and that key flips once a screening record is attached. Check all of them so
      // a skip is never orphaned (which was re-gating the BOV after the key changed).
      try {
        const _ov = loadAssignOverlay();
        const _cand = [_lk];
        if (_sd.screenId) _cand.push('s_' + _sd.screenId);
        if (_sd.id) _cand.push('d_' + _sd.id);
        scrSkip = _cand.some(k => _ov[k] && _ov[k].screeningSkipped);
        ivSkip = _cand.some(k => _ov[k] && _ov[k].interviewSkipped);
      } catch (e) {}
      try { if (_sd.screenId) { const _sc = (loadScreens() || []).find(s => s.id === _sd.screenId); if (_sc && (_sc.callState === 'complete' || _sc.completed === true)) scr = true; } } catch (e) {}
      if (!scr && scrSkip) scr = true;
      let fin = false, lse = false, _rmid = '';
      try { const _rm = roomForDeal(_sd); if (_rm) { _rmid = _rm.id || ''; (_rm.docs || []).forEach(d => { const c = d && d.category; if (c && c.indexOf('Financials') === 0) fin = true; if (c === 'Lease') lse = true; }); if (_rm.noLease) lse = true; } } catch (e) {}
      let _bov = null;
      try { _bov = loadBovs().filter(b => b && b.listingKey === _lk).sort((a, b2) => String(b2.createdAt || '').localeCompare(String(a.createdAt || '')))[0] || null; } catch (e) {}
      if (_bov) { if (!fin && Array.isArray(_bov.financials) && _bov.financials.length) fin = true; if (!lse && Array.isArray(_bov.lease) && _bov.lease.length) lse = true; }
      let ivDone = false, ivId = '', ivRoom = '';
      try { const ivs = loadInterviews().filter(iv => ((iv.dealKey === _lk) || (_rmid && iv.roomId === _rmid)) && linkKind(iv.kind) === 'valuation').sort((a, b2) => String(b2.createdAt || '').localeCompare(String(a.createdAt || ''))); if (ivs.length) { ivDone = true; ivId = ivs[0].id; ivRoom = ivs[0].roomId || ''; } } catch (e) {}
      try { if (!ivDone) { const sls = loadSellerLinks().filter(x => x.dealKey === _lk && linkKind(x.kind) === 'valuation'); if (sls.some(sl => (sl.form && sl.form.submittedAt) || ((sl.videoCount || 0) > 0))) ivDone = true; } } catch (e) {}
      const _q = ivDone || ivSkip;
      const _state = _bov ? (_bov.finalizedAt ? 'final' : (_bov.aiGenerated && !_bov.pending ? 'built' : 'requested')) : '';
      return res.json({ ok: true, listingKey: _lk, screening: scr, screeningSkipped: scrSkip, questionnaire: _q, interviewDone: ivDone, interviewSkipped: ivSkip, interviewId: ivId, interviewRoomId: ivRoom, financials: fin, lease: lse, ready: !!(_q && fin && lse), bovId: _bov ? _bov.id : '', state: _state });
    }
    if (!pid && !cid) return res.json({ ok: true, screening: false, questionnaire: false, financials: false, lease: false, ready: false, bovId: '', state: '' });
    const questionnaire = loadQuests().some(q => hit(q) && (q.completed || q.processed));
    const bovs = loadBovs().filter(hit).sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
    const bov = bovs[0] || null;
    let financials = !!(bov && Array.isArray(bov.financials) && bov.financials.length);
    let lease = !!(bov && Array.isArray(bov.lease) && bov.lease.length);
    if (!financials || !lease) {
      try {
        const deals = loadDeals().filter(hit);
        const dealIds = new Set(deals.map(d => d.id));
        const roomIds = new Set(deals.map(d => d.roomId).filter(Boolean));
        loadRooms().forEach(r => {
          if (!(roomIds.has(r.id) || dealIds.has(r.srcDealId) || hit(r))) return;
          (r.docs || []).forEach(d => { const c = d && d.category; if (c && c.indexOf('Financials') === 0) financials = true; if (c === 'Lease') lease = true; });
          if (r.noLease) lease = true;
        });
      } catch (e) {}
    }
    // "On file" means a COMPLETED (or skipped) screening — not a call that was merely started
    // and backed out of. An abandoned call leaves a 'live'/'pending' record; it must NOT flip the
    // menu step to done or unlock the data-room / Seller Interview steps. (Skip is handled below.)
    let screening = (function(){ try { return (loadScreens()||[]).some(function(sc){ var d=sc.data||{}; var matches=(pid && (d.personId===pid || d.contactPersonId===pid || sc.personId===pid)) || (cid && (d.companyId===cid || sc.companyId===cid)); return matches && (sc.callState==='complete' || sc.completed===true); }); } catch(e){ return false; } })();
    let screeningSkipped = false, interviewSkipped = false;
    // Check BOTH the s_<screenId> and d_<id> keys per deal — the overlay key flips when a screening
    // record is attached, and a skip written under the old key must still count.
    try { const _ov = loadAssignOverlay(); loadDeals().filter(hit).forEach(function(d){ const ks = []; if (d.screenId) ks.push('s_'+d.screenId); if (d.id) ks.push('d_'+d.id); ks.forEach(function(k){ if (_ov[k] && _ov[k].screeningSkipped) screeningSkipped = true; if (_ov[k] && _ov[k].interviewSkipped) interviewSkipped = true; }); }); } catch(e){}
    if (!screening && screeningSkipped) screening = true;
    // A seller-completed interview (self-serve form or video) satisfies the questionnaire input.
    let interviewDone = false, interviewId = '', interviewRoomId = '';
    try {
      const sl = loadSellerLinks().find(x => ((pid && x.personId === pid) || (cid && x.companyId === cid)) && linkKind(x.kind) === 'valuation');
      if (sl && ((sl.form && sl.form.submittedAt) || (sl.videoCount || 0) > 0)) interviewDone = true;
      const ivs = loadInterviews().filter(iv => ((pid && iv.personId === pid) || (cid && iv.companyId === cid)) && linkKind(iv.kind) === 'valuation').sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
      if (ivs.length) { interviewDone = true; interviewId = ivs[0].id; interviewRoomId = ivs[0].roomId || ''; }
    } catch (e) {}
    const q = questionnaire || interviewDone || interviewSkipped;
    const state = bov ? (bov.finalizedAt ? 'final' : (bov.aiGenerated && !bov.pending ? 'built' : 'requested')) : '';
    res.json({ ok: true, screening: screening, screeningSkipped: screeningSkipped, questionnaire: q, interviewDone: interviewDone, interviewSkipped: interviewSkipped, interviewId: interviewId, interviewRoomId: interviewRoomId, financials: financials, lease: lease, ready: !!(q && financials && lease), bovId: bov ? bov.id : '', state: state });
  } catch (e) { res.status(500).json({ ok: false, error: String((e && e.message) || e) }); }
});

// Find-or-create the data room for a contact (independent of a deal), so a rep can
// collect financials & lease for a valuation at any time. Tags the room with
// personId/companyId so it resolves consistently and feeds valuation-readiness.
app.post('/api/valuation-room', express.json(), (req, res) => {
  try {
    const b = req.body || {};
    const _canRoom = userCan(req.user, 'tool:rrg_rooms_queue.html');
    const pid = String(b.personId || '').trim().slice(0, 48);
    const cid = String(b.companyId || '').trim().slice(0, 48);
    // Listing-scoped: a specific business's data room (create-or-find tied to that deal).
    const _lk = String(b.listingKey || '').trim().slice(0, 64);
    const _sd = _lk ? _dealFromListingKey(_lk) : null;
    if (_lk && _sd) {
      const _rm = roomForDeal(_sd);
      if (_rm) return res.json({ ok: true, id: _rm.id });
      if (!_canRoom) return res.status(403).json({ ok: false, error: 'You do not have permission to set up data rooms.' });
      const _rooms = loadRooms();
      const nr = { id: newRoomId(), srcCimId: '', srcBovId: '', srcDealId: _sd.id, personId: pid || _sd.contactPersonId || '', companyId: cid || _sd.companyId || '', token: newRoomToken(), business: String(b.business || _sd.business || 'Valuation').slice(0, 120), by: (req.user && req.user.name) || '', byUser: (req.user && req.user.username) || '', createdAt: new Date().toISOString(), folders: roomCategories(), docs: [], access: [], grants: [] };
      _rooms.push(nr); saveRooms(_rooms);
      try { const _ds = loadDeals(); const _d2 = _ds.find(x => x.id === _sd.id); if (_d2 && !_d2.roomId) { _d2.roomId = nr.id; saveDeals(_ds); } } catch (e) {}
      return res.json({ ok: true, id: nr.id });
    }
    if (!pid && !cid) return res.status(400).json({ ok: false, error: 'No contact.' });
    const hit = o => !!o && ((pid && (o.personId === pid || o.contactPersonId === pid)) || (cid && o.companyId === cid));
    const rooms = loadRooms();
    let room = rooms.find(hit) || null;
    if (!room) {
      try { const deals = loadDeals().filter(hit); for (const d of deals) { const rm = rooms.find(r => r.id === d.roomId || r.srcDealId === d.id); if (rm) { room = rm; break; } } } catch (e) {}
    }
    if (!room) {
      if (!_canRoom) return res.status(403).json({ ok: false, error: 'You do not have permission to set up data rooms.' });
      room = { id: newRoomId(), srcCimId: '', srcBovId: '', srcDealId: '', personId: pid, companyId: cid, token: newRoomToken(), business: String(b.business || 'Valuation').slice(0, 120), by: (req.user && req.user.name) || '', byUser: (req.user && req.user.username) || '', createdAt: new Date().toISOString(), folders: roomCategories(), docs: [], access: [], grants: [] };
      rooms.push(room); saveRooms(rooms);
    } else if ((pid && !room.personId) || (cid && !room.companyId)) {
      if (pid && !room.personId) room.personId = pid;
      if (cid && !room.companyId) room.companyId = cid;
      saveRooms(rooms);
    }
    res.json({ ok: true, id: room.id });
  } catch (e) { res.status(500).json({ ok: false, error: String((e && e.message) || e) }); }
});

// Skip the Seller Screening Call for a seller we already know / already want. Marks the
// listing qualified, advances it straight to Data Collection, ensures a data room exists,
// and logs why + who — same destination as a completed screen, minus the call.
app.post('/api/seller/skip-screening', express.json(), (req, res) => {
  try {
    const b = req.body || {};
    const pid = String(b.personId || '').trim().slice(0, 48);
    const cid = String(b.companyId || '').trim().slice(0, 48);
    if (!pid && !cid) return res.status(400).json({ ok: false, error: 'No contact.' });
    const hit = o => !!o && ((pid && (o.personId === pid || o.contactPersonId === pid)) || (cid && o.companyId === cid));
    const now = new Date().toISOString();
    const ppl = loadPeople();
    const person = pid ? (ppl.find(p => p.id === pid) || null) : null;
    const company = cid ? (companyById(cid) || null) : null;
    const bizName = (company && company.name) || (person && (person.company || person.name)) || 'Seller';
    const market = (company && company.market) || '';
    const address = (company && company.office && [company.office.address, company.office.city, company.office.state].filter(Boolean).join(', ')) || '';
    const repName = (req.user && req.user.name) || '';
    const repUser = (req.user && req.user.username) || '';
    // Find or open the listing for this seller. When a listingKey is supplied, act on that
    // specific business; otherwise fall back to the seller's first listing (single-business).
    const deals = loadDeals();
    const _lk = String(b.listingKey || '').trim().slice(0, 64);
    let deal = null;
    if (_lk) { if (_lk.slice(0, 2) === 's_') deal = deals.find(d => d.screenId === _lk.slice(2)) || null; else if (_lk.slice(0, 2) === 'd_') deal = deals.find(d => d.id === _lk.slice(2)) || null; }
    if (!deal) deal = deals.filter(hit)[0] || null;
    if (!deal) {
      deal = { id: newDealId(), business: String(bizName).slice(0, 120), market: market, contact: (person && person.name) || '', screenId: '', roomId: '', contactPersonId: pid || '', companyId: cid || '', createdAt: now, by: repName, byUser: repUser };
      deals.push(deal);
    }
    // Pre-qualified (known seller): we skip the screening CALL and do NOT create a screening
    // form/record \u2014 there's nothing to fill out for a seller we already know. The screening
    // gate is satisfied by the screeningSkipped overlay flag set on the listing below.
    deal.startedAt = deal.startedAt || now;
    // Ensure a data room exists so financials & lease can go in.
    const rooms = loadRooms();
    let room = rooms.find(hit) || rooms.find(r => r.id === deal.roomId || r.srcDealId === deal.id) || null;
    if (!room) {
      room = { id: newRoomId(), srcCimId: '', srcBovId: '', srcDealId: deal.id, personId: pid, companyId: cid, token: newRoomToken(), business: String(bizName).slice(0, 120), by: repName, byUser: repUser, createdAt: now, folders: roomCategories(), docs: [], access: [], grants: [] };
      rooms.push(room); saveRooms(rooms);
    }
    if (!deal.roomId) deal.roomId = room.id;
    saveDeals(deals);
    // Advance to Data Collection. Key off an existing screening if one already exists on this
    // listing, otherwise the listing's own d_<id> key \u2014 no new screening record is created.
    const key = deal.screenId ? ('s_' + deal.screenId) : ('d_' + deal.id);
    const ov = loadAssignOverlay();
    if (deal.screenId) { const _oldKey = 'd_' + deal.id; if (ov[_oldKey] && !ov[key]) { ov[key] = ov[_oldKey]; delete ov[_oldKey]; } }
    const cur = ov[key] || {};
    let stageName = '';
    const _plid = pipelineForCategory('businessSale') || 'p_bizsales';
    const _pl = loadPipelines().find(x => x.id === _plid);
    const _stg = (_pl && Array.isArray(_pl.stages)) ? _pl.stages : [];
    if (_stg.length) {
      let _tgt = _stg.findIndex(st => /data collect/i.test(st.name || ''));
      if (_tgt < 0) _tgt = _stg.findIndex(st => /valuation/i.test(st.name || ''));
      if (_tgt < 0) _tgt = Math.min(2, _stg.length - 1);
      cur.stageFlags = cur.stageFlags || {};
      for (let i = 0; i < _tgt; i++) cur.stageFlags['g' + i] = true;
      stageName = (_stg[_tgt] && _stg[_tgt].name) || cur.pipelineStage || '';
      cur.pipelineStage = stageName;
    }
    cur.pipelineId = _plid; cur.status = 'Active'; cur.screeningSkipped = true;
    cur.updatedAt = now; cur.stageSince = now;
    ov[key] = cur; saveAssignOverlay(ov);
    // Audit trail on the seller's Activity Log.
    if (person) {
      logActivity(person, 'Note', 'Seller Screening Call skipped \u2014 pre-qualified (known seller). Listing moved to ' + (stageName || 'Data Collection') + '.', { by: repName, byUser: repUser, auto: true });
      savePeople(ppl);
    }
    res.json({ ok: true, screenId: deal.screenId || '', key: key, roomId: room.id, stage: stageName || 'Data Collection' });
  } catch (e) { res.status(500).json({ ok: false, error: String((e && e.message) || e) }); }
});

// Skip the Seller Interview for a listing that doesn't need one — unlocks the valuation.
app.post('/api/seller/skip-interview', express.json(), (req, res) => {
  try {
    const b = req.body || {};
    const pid = String(b.personId || '').trim().slice(0, 48);
    const cid = String(b.companyId || '').trim().slice(0, 48);
    let key = String(b.listingKey || '').trim().slice(0, 64);
    if (!key) { const hit = o => !!o && ((pid && (o.personId === pid || o.contactPersonId === pid)) || (cid && o.companyId === cid)); const d = loadDeals().filter(hit)[0]; if (d) key = d.screenId ? ('s_' + d.screenId) : ('d_' + d.id); }
    if (!key) return res.status(400).json({ ok: false, error: 'No listing to skip the interview on.' });
    const now = new Date().toISOString();
    const ov = loadAssignOverlay(); const cur = ov[key] || {};
    cur.interviewSkipped = true; cur.updatedAt = now; ov[key] = cur; saveAssignOverlay(ov);
    try { const ppl = loadPeople(); const person = pid ? ppl.find(p => p.id === pid) : null; if (person) { logActivity(person, 'Note', 'Seller Interview skipped — not needed for this listing. Valuation unlocked.', { by: (req.user && req.user.name) || '', byUser: (req.user && req.user.username) || '', auto: true }); savePeople(ppl); } } catch (e) {}
    res.json({ ok: true, key: key });
  } catch (e) { res.status(500).json({ ok: false, error: String((e && e.message) || e) }); }
});

// Undo a mistaken skip (screening or interview) — clears the flag so the step is required again.
app.post('/api/seller/unskip', express.json(), (req, res) => {
  try {
    const b = req.body || {};
    const pid = String(b.personId || '').trim().slice(0, 48);
    const cid = String(b.companyId || '').trim().slice(0, 48);
    const which = String(b.which || '').trim();
    const _lk = String(b.listingKey || '').trim().slice(0, 64);
    const ov = loadAssignOverlay();
    const hit = o => !!o && ((pid && (o.personId === pid || o.contactPersonId === pid)) || (cid && o.companyId === cid));
    const keys = []; if (_lk) keys.push(_lk); loadDeals().filter(hit).forEach(d => { if (d.screenId) keys.push('s_' + d.screenId); if (d.id) keys.push('d_' + d.id); });
    let changed = false;
    keys.forEach(k => { const cur = ov[k]; if (!cur) return; if ((which === 'screening' || !which) && cur.screeningSkipped) { delete cur.screeningSkipped; changed = true; cur.updatedAt = new Date().toISOString(); } if ((which === 'interview' || !which) && cur.interviewSkipped) { delete cur.interviewSkipped; changed = true; cur.updatedAt = new Date().toISOString(); } });
    if (changed) saveAssignOverlay(ov);
    try { const ppl = loadPeople(); const person = pid ? ppl.find(p => p.id === pid) : null; if (person && changed) { logActivity(person, 'Note', (which === 'interview' ? 'Seller Interview skip undone — interview needed again.' : 'Seller Screening skip undone — screening needed again.'), { by: (req.user && req.user.name) || '', byUser: (req.user && req.user.username) || '', auto: true }); savePeople(ppl); } } catch (e) {}
    res.json({ ok: true, changed: changed });
  } catch (e) { res.status(500).json({ ok: false, error: String((e && e.message) || e) }); }
});

// Ensure a valuation (BOV) record exists for a contact — reuse the latest one, else
// create a pending one from the contact's most recent questionnaire. Returns bovId so
// the "Generate Valuation" action can open the generate screen.
app.post('/api/valuation-ensure', express.json(), (req, res) => {
  try {
    const b = req.body || {};
    const pid = String(b.personId || '').trim().slice(0, 48);
    const cid = String(b.companyId || '').trim().slice(0, 48);
    if (!pid && !cid) return res.status(400).json({ ok: false, error: 'No contact.' });
    const _lk = String(b.listingKey || '').trim().slice(0, 64);
    const hit = o => !!o && ((pid && (o.personId === pid || o.contactPersonId === pid)) || (cid && o.companyId === cid));
    const byNew = (a, b2) => String(b2.createdAt || '').localeCompare(String(a.createdAt || ''));
    // When scoped to one listing, only reuse a BOV tagged to THAT listing — never another
    // business's valuation. Otherwise fall back to the person/company aggregate (unchanged).
    const bov = _lk ? (loadBovs().filter(x => x && x.listingKey === _lk).sort(byNew)[0] || null) : (loadBovs().filter(hit).sort(byNew)[0] || null);
    if (bov) return res.json({ ok: true, bovId: bov.id });
    const arr = loadQuests();
    let q = arr.filter(hit).sort(byNew)[0] || null;
    // No formal questionnaire on file? A completed Seller Interview (form or video) IS the
    // questionnaire now — synthesize one from it so the valuation can proceed.
    if (!q) q = synthQuestFromInterview(req, pid, cid);
    if (!q) {
      // The interview was deliberately SKIPPED — no questionnaire is expected. Don't bounce the
      // broker back to "send the interview"; stand up a bare valuation so it can build straight
      // from the financials & lease. (Checks both overlay keys, like valuation-readiness.)
      let ivSkipped = false;
      try {
        const _ov = loadAssignOverlay(); const _cand = [];
        if (_lk) { _cand.push(_lk); const _sd = _dealFromListingKey(_lk); if (_sd) { if (_sd.screenId) _cand.push('s_' + _sd.screenId); if (_sd.id) _cand.push('d_' + _sd.id); } }
        else { loadDeals().filter(hit).forEach(function (d) { if (d.screenId) _cand.push('s_' + d.screenId); if (d.id) _cand.push('d_' + d.id); }); }
        ivSkipped = _cand.some(k => _ov[k] && _ov[k].interviewSkipped);
      } catch (e) {}
      if (ivSkipped) {
        let biz = '', mkt = '';
        try { const _sd = _lk ? _dealFromListingKey(_lk) : (loadDeals().filter(hit)[0] || null); if (_sd) { biz = _sd.business || ''; mkt = _sd.market || _sd.city || ''; } } catch (e) {}
        if (!biz && cid) { try { const _c = loadCompanies().find(c => c.id === cid); if (_c) biz = _c.name || ''; } catch (e) {} }
        const _arr = loadBovs();
        const rec = { id: newBovId(), srcFormId: '', srcQuestId: '', pending: true, interviewSkipped: true,
          personId: pid || '', companyId: cid || '', listingKey: _lk || '',
          business: biz || 'Business', market: mkt || '', date: '', rangeText: '', targetText: '', multText: '', ebitdaText: '',
          by: (req.user && req.user.name) || '', byUser: (req.user && req.user.username) || '', createdAt: new Date().toISOString() };
        _arr.push(rec); saveBovs(_arr);
        return res.json({ ok: true, bovId: rec.id });
      }
      // No questionnaire and no interview yet — stand up a bare valuation anyway so the rep can
      // get moving; the BOV builder then collects the financials, lease and remaining inputs.
      let _biz = '', _mkt = '';
      try { const _sd = _lk ? _dealFromListingKey(_lk) : (loadDeals().filter(hit)[0] || null); if (_sd) { _biz = _sd.business || ''; _mkt = _sd.market || _sd.city || ''; } } catch (e) {}
      if (!_biz && cid) { try { const _c = loadCompanies().find(c => c.id === cid); if (_c) _biz = _c.name || ''; } catch (e) {} }
      const _arr2 = loadBovs();
      const rec2 = { id: newBovId(), srcFormId: '', srcQuestId: '', pending: true,
        personId: pid || '', companyId: cid || '', listingKey: _lk || '',
        business: _biz || 'Business', market: _mkt || '', date: '', rangeText: '', targetText: '', multText: '', ebitdaText: '',
        by: (req.user && req.user.name) || '', byUser: (req.user && req.user.username) || '', createdAt: new Date().toISOString() };
      _arr2.push(rec2); saveBovs(_arr2);
      return res.json({ ok: true, bovId: rec2.id });
    }
    if (!q.processed) { const arr2 = loadQuests(); const q2 = arr2.find(x => x.id === q.id) || q; q2.processed = true; q2.processedAt = new Date().toISOString(); saveQuests(arr2); }
    const nb = ensureBovForQuest(q);
    // Tag the new valuation to the specific listing so its state resolves per-business.
    if (_lk && nb && nb.id) { try { const _bs = loadBovs(); const _bb = _bs.find(x => x.id === nb.id); if (_bb && !_bb.listingKey) { _bb.listingKey = _lk; saveBovs(_bs); } } catch (e) {} }
    res.json({ ok: true, bovId: (nb && nb.id) || '' });
  } catch (e) { res.status(500).json({ ok: false, error: String((e && e.message) || e) }); }
});

