// Upload a document into a room.
app.post('/api/room-upload', express.json({ limit: '40mb' }), (req, res) => {
  const b = req.body || {};
  const arr = loadRooms();
  const r = arr.find(x => x.id === b.roomId);
  if (!r) return res.status(404).json({ ok: false, error: 'Data room not found.' });
  if (!ownsRoom(req, r)) return res.status(403).json({ ok: false, error: 'Not yours.' });
  const orig = String(b.filename || '').trim();
  const m = orig.match(/\.([a-z0-9]+)$/i); const ext = m ? m[1].toLowerCase() : '';
  if (ext === 'zip') {
    if (!r.allowZip) return res.status(400).json({ ok: false, error: 'ZIP uploads are off for this room. Turn on "Allow ZIP files" in the room to auto-extract and file the contents.' });
    const zdata = String(b.dataB64 || ''); if (!zdata) return res.status(400).json({ ok: false, error: 'No file data received.' });
    const _zc = (b.category === '' ? '' : (roomServeCats(r).indexOf(b.category) >= 0 ? b.category : ''));
    const _zmode = (['extract','store','both'].indexOf(String(b.zipMode||'')) >= 0) ? String(b.zipMode) : 'both';
    const zres = ingestZipToRoom(r, { name: orig, dataB64: zdata }, { category: _zc, by: (req.user && req.user.name) || '', mode: _zmode });
    if (!zres || zres.error) return res.status(400).json({ ok: false, error: (zres && zres.error) || 'Could not process the zip.' });
    saveRooms(arr);
    return res.json({ ok: true, docs: r.docs, extracted: zres.added, skipped: zres.skipped, zip: true });
  }
  if (!ROOM_EXT.test(ext)) return res.status(400).json({ ok: false, error: 'That file type isn\'t supported. Use PDF, Word, Excel, CSV, PowerPoint, an image, or text.' });
  const data = String(b.dataB64 || ''); if (!data) return res.status(400).json({ ok: false, error: 'No file data received.' });
  let buf; try { buf = Buffer.from(data, 'base64'); } catch (e) { return res.status(400).json({ ok: false, error: 'Could not read the file data.' }); }
  if (!buf.length) return res.status(400).json({ ok: false, error: 'The file appears to be empty.' });
  if (buf.length > 25 * 1024 * 1024) return res.status(400).json({ ok: false, error: 'File too large (max 25 MB).' });
  // Duplicate detection: flag an identical file (same content hash) or a same-name file already
  // in this room, unless the uploader confirms with force:true.
  const hash = crypto.createHash('sha256').update(buf).digest('hex');
  if (!b.force) {
    const byHash = (r.docs || []).find(d => d.hash && d.hash === hash);
    const byName = (r.docs || []).find(d => String(d.originalName || '').trim().toLowerCase() === orig.toLowerCase());
    const dup = byHash || byName;
    if (dup) return res.json({ ok: false, duplicate: true, reason: byHash ? 'content' : 'name', existing: { title: dup.title || dup.originalName || '', originalName: dup.originalName || '', category: dup.category || '', uploadedAt: dup.uploadedAt || '' } });
  }
  const _rcats = roomServeCats(r);
  const category = (b.category === '' ? '' : (_rcats.indexOf(b.category) >= 0 ? b.category : 'Other'));
  const title = String(b.title || '').trim().slice(0, 140) || prettyName(orig);
  try { if (!fs.existsSync(ROOMS_DIR)) fs.mkdirSync(ROOMS_DIR, { recursive: true }); } catch (e) { return res.status(500).json({ ok: false, error: 'Could not create the rooms folder.' }); }
  const id = newRoomDocId();
  try { binWrite(path.join(ROOMS_DIR, id + '.' + ext), buf); } catch (e) { return res.status(500).json({ ok: false, error: 'Could not save the file.' }); }
  r.docs = r.docs || [];
  r.docs.push({ id, title, category, ext, originalName: orig, size: buf.length, hash: hash, uploadedAt: new Date().toISOString(), by: (req.user && req.user.name) || '' });
  if (!r.builtAt) r.builtAt = new Date().toISOString();
  saveRooms(arr);
  res.json({ ok: true, docs: r.docs });
});
// Mass upload — Claude reads each file and files it into the right folder automatically.
// Instant name-based folder guess — the fallback when the AI classifier is slow or off.
function roomCatFromName(name, cats) {
  const s = String(name || '').toLowerCase();
  const has = (...ws) => ws.some(w => s.indexOf(w) >= 0);
  let c = 'Other';
  if (has('p&l', 'p_l', 'p and l', 'profit', 'income statement', 'balance sheet', 'financ', 'sde', 'add-back', 'revenue', 'sales report', 'bank statement')) c = 'Financials';
  else if (has('tax', '1120', '1065', '1040', 'w-2', 'w2', 'w-9', 'w9', 'k-1', '1099', 'return')) c = 'Tax Returns';
  else if (has('lease', 'sublease', 'estoppel', 'rent roll', 'loi', 'amendment')) c = 'Lease';
  else if (has('equip', 'ff&e', 'ffe', 'inventory', 'asset')) c = 'Equipment & FF&E';
  else if (has('license', 'permit', 'tabc', 'liquor', 'health', 'occupancy', 'certificate')) c = 'Licenses & Permits';
  else if (has('operating agreement', 'bylaw', 'contract', 'nda', 'entity', 'articles', 'legal', 'assignment')) c = 'Legal & Corporate';
  else if (has('menu', 'marketing', 'flyer', 'press', 'photo', 'brochure', 'teaser')) c = 'Menus & Marketing';
  return (Array.isArray(cats) && cats.indexOf(c) >= 0) ? c : 'Other';
}
app.post('/api/room/:id/bulk-upload', express.json({ limit: '80mb' }), async (req, res) => {
  const arr = loadRooms();
  const r = arr.find(x => x.id === req.params.id);
  if (!r) return res.status(404).json({ ok: false, error: 'Data room not found.' });
  if (!ownsRoom(req, r)) return res.status(403).json({ ok: false, error: 'Not yours.' });
  const files = Array.isArray((req.body || {}).files) ? (req.body.files || []).slice(0, 40) : [];
  if (!files.length) return res.status(400).json({ ok: false, error: 'No files received.' });
  const _zmode = (['extract','store','both'].indexOf(String((req.body||{}).zipMode||'')) >= 0) ? String((req.body||{}).zipMode) : 'both';
  const _rc = roomServeCats(r);
  // Classify by file name only — fast. AI sorts when it answers quickly; otherwise a name
  // heuristic files each doc so the upload NEVER stalls on a slow/unavailable AI call.
  const items = files.map((f, i) => ({ name: String((f && f.filename) || ('File ' + (i + 1))) }));
  const byIdx = {};
  try {
    const cls = await Promise.race([
      aiassist.classifyRoomDocs({ items, categories: _rc }),
      new Promise(resolve => setTimeout(() => resolve(null), 15000)),
    ]);
    if (Array.isArray(cls)) cls.forEach(c => { if (Number.isInteger(c.i)) byIdx[c.i] = c.category; });
  } catch (e) { console.error('classifyRoomDocs:', e && e.message); }
  const results = []; let added = 0;
  for (let i = 0; i < files.length; i++) {
    const f = files[i] || {};
    const _fn = String(f.filename || ''); const _fm = _fn.match(/\.([a-z0-9]+)$/i); const _fe = _fm ? _fm[1].toLowerCase() : '';
    if (_fe === 'zip') {
      if (!r.allowZip) { results.push({ ok:false, name:_fn, error:'ZIP is off for this room — enable "Allow ZIP files" first.' }); continue; }
      const zres = ingestZipToRoom(r, { name:_fn, dataB64:f.dataB64 }, { by: ((req.user && req.user.name) || '') + ' · zip', mode:_zmode });
      if (zres && zres.ok) { added += zres.added + (zres.zipDoc ? 1 : 0); results.push({ ok:true, name:_fn, category:'(zip — extracted '+zres.added+')', id: zres.zipDoc && zres.zipDoc.id }); (zres.results||[]).forEach(function(rr){ results.push(rr); }); }
      else { results.push({ ok:false, name:_fn, error:(zres && zres.error) || 'Could not process the zip.' }); }
      continue;
    }
    const cat = _rc.indexOf(byIdx[i]) >= 0 ? byIdx[i] : roomCatFromName(f.filename, _rc);
    const out = addFileToRoomEx(r, { name: f.filename, dataB64: f.dataB64 }, { category: cat, title: (String(f.title || '').trim() || prettyName(f.filename || '')), by: ((req.user && req.user.name) || '') + ' · AI-filed', source: 'bulk:' + Date.now() + ':' + i });
    if (out && out.doc) { added++; results.push({ ok: true, name: f.filename || '', category: cat, id: out.doc.id }); }
    else { const reason = (out && out.error) || 'Skipped.'; console.error('bulk-upload skip:', f.filename || ('file ' + (i + 1)), '→', reason); results.push({ ok: false, name: f.filename || '', category: cat, error: reason }); }
  }
  if (added) saveRooms(arr);
  res.json({ ok: true, added, results, docs: r.docs || [] });
});
