    const room = ensureRoomForScreen(req, rec);
    if (deal && room) { const dd = loadDeals(); const d2 = dd.find(x => x.id === deal.id); if (d2 && d2.roomId !== room.id) { d2.roomId = room.id; saveDeals(dd); } }

