            + ((room && !hadRoom) ? ', data room set up' : (room ? ', data room ready' : ''))
            + (pipeName ? (', routed to the ' + pipeName + ' pipeline') : '') + '.'
            + (_dtxt ? (' Call length: ' + _dtxt + '.') : '');
