// Location photos — a couple of images per location, stored on the data disk.
const LOCPHOTO_DIR = path.join(BOV_DATA_DIR, 'locphotos');
const LOCPHOTO_MAX = 5;
const USERPHOTO_DIR = path.join(BOV_DATA_DIR, 'userphotos');
