  for (let _i = 0; _i < _pnames.length && (l.photos || []).length < LOCPHOTO_MAX; _i++) { const p = await placesPhotoNew(key, _pnames[_i]); if (attachPhotoBuffer(l, p.img, 'places')) added++; else { if (p.reason) reasons.push(p.reason); break; } }
