const ANTHROPIC_KEY_FILE = path.join(BOV_DATA_DIR, 'anthropic.key');
function loadAnthropicKeyFile() { try { const t = fs.readFileSync(ANTHROPIC_KEY_FILE, 'utf8').trim(); return t || ''; } catch (e) { return ''; } }
function saveAnthropicKey(k) { try { if (!fs.existsSync(BOV_DATA_DIR)) fs.mkdirSync(BOV_DATA_DIR, { recursive: true }); fs.writeFileSync(ANTHROPIC_KEY_FILE, String(k || '').trim()); } catch (e) {} }
// At boot, a saved key file overrides the environment so the generators pick it up.
(function () { const k = loadAnthropicKeyFile(); if (k) process.env.ANTHROPIC_API_KEY = k; })();
app.get('/api/admin/activity', requireAdmin, (req, res) => {
  const logins = auth.readLogins().slice(-300).reverse();
  const usageAll = auth.readUsage();
  const byTool = {}, byUser = {};
  usageAll.forEach(u => { byTool[u.tool] = (byTool[u.tool]||0)+1; byUser[u.username] = (byUser[u.username]||0)+1; });
  const byToolOut = Object.entries(byTool).sort((a,b)=>b[1]-a[1]).map(x=>({ tool:x[0]||'', count:x[1] }));
  const byUserOut = Object.entries(byUser).sort((a,b)=>b[1]-a[1]).map(x=>({ user:x[0]||'', count:x[1] }));
  const usage = usageAll.slice(-500).reverse().map(u => ({ when: fmtWhen(u.timestamp), ts: u.timestamp||'', user: u.username||'', tool: u.tool||'', ip: u.ip||'' }));
  const loginsOut = logins.map(l => ({ when: fmtWhen(l.timestamp), ts: l.timestamp||'', user: l.username||'', result: l.result||'', ip: l.ip||'' }));
  res.json({ ok:true, byTool: byToolOut, byUser: byUserOut, usage, logins: loginsOut });
});
// Quick record counts of the main data stores — the overview strip on the Activity page.
app.get('/api/admin/record-counts', requireAdmin, (req, res) => {
  const n = a => { try { return (a || []).length; } catch (e) { return 0; } };
  const companies = loadCompanies();
  let concepts = 0, locations = 0;
  companies.forEach(c => { concepts += (Array.isArray(c.concepts) ? c.concepts.length : 0); locations += (Array.isArray(c.locations) ? c.locations.length : 0); });
  res.json({ ok: true, counts: [
    { key: 'contacts',   label: 'Contacts',          count: n(loadPeople()),     href: 'rrg_people.html',       primary: true },
    { key: 'companies',  label: 'Companies',         count: companies.length,    href: 'rrg_companies.html',    primary: true },
    { key: 'listings',   label: 'Listings',          count: n(loadDeals()),      href: 'rrg_board.html',        primary: true },
    { key: 'datarooms',  label: 'Data Rooms',        count: n(loadRooms()),      href: 'rrg_rooms_queue.html',  primary: true },
    { key: 'concepts',   label: 'Concepts',          count: concepts,            href: 'rrg_companies.html' },
    { key: 'locations',  label: 'Locations',         count: locations,           href: 'rrg_companies.html' },
    { key: 'files',      label: 'Uploaded Files',    count: n(loadUserFiles()),  href: 'rrg_documents.html' },
    { key: 'valuations', label: 'Valuations',        count: n(loadBovs()),       href: 'rrg_bov_queue.html' },
    { key: 'marketing',  label: 'Marketing Packs',   count: n(loadCims()),       href: 'rrg_cim_queue.html' },
    { key: 'lois',       label: 'LOIs',              count: n(loadLois()),        href: 'rrg_documents.html' },
    { key: 'agreements', label: 'Agreements',        count: n(loadAgreements()), href: 'rrg_agreements.html' },
    { key: 'interviews', label: 'Seller Interviews', count: n(loadInterviews()) },
    { key: 'screenings', label: 'Screening Calls',   count: n(loadScreens()) },
  ] });
});
// Full tool-open + sign-in history for ONE user, for the sessions drill-down on the Activity page.
app.get('/api/admin/user-activity', requireAdmin, (req, res) => {
  const user = String((req.query && req.query.user) || '').trim();
  if (!user) return res.status(400).json({ ok: false, error: 'No user given.' });
  const usage = auth.readUsage().filter(u => u.username === user).slice(-3000)
    .map(u => ({ when: fmtWhen(u.timestamp), ts: u.timestamp || '', tool: u.tool || '', ip: u.ip || '' }));
  const logins = auth.readLogins().filter(l => l.username === user).slice(-800)
    .map(l => ({ when: fmtWhen(l.timestamp), ts: l.timestamp || '', result: l.result || '', ip: l.ip || '' }));
  res.json({ ok: true, user: user, usage: usage, logins: logins });
});
app.get('/api/admin/anthropic-key', requireAdmin, (req, res) => res.json({ ok: true, set: !!process.env.ANTHROPIC_API_KEY, fromFile: !!loadAnthropicKeyFile(), fromEnv: !loadAnthropicKeyFile() && !!process.env.ANTHROPIC_API_KEY }));
app.post('/api/admin/anthropic-key', requireAdmin, express.json(), (req, res) => {
  const b = req.body || {};
  if (b.clear) { saveAnthropicKey(''); return res.json({ ok: true, set: !!process.env.ANTHROPIC_API_KEY, fromFile: false, note: 'Cleared the saved key. The environment key (if any) is used after the next restart.' }); }
  const k = String(b.key || '').trim();
  if (!k) return res.status(400).json({ ok: false, error: 'Paste an Anthropic API key.' });
  if (!/^sk-ant-[A-Za-z0-9_\-]{20,}$/.test(k)) return res.status(400).json({ ok: false, error: 'That doesn’t look like an Anthropic API key (they start with sk-ant-).' });
  saveAnthropicKey(k); process.env.ANTHROPIC_API_KEY = k;
  res.json({ ok: true, set: true, fromFile: true });
});

