  try { const ags = loadAgreements(); let ch = false; ags.forEach(a => { if (a.companyId && isLoser(a.companyId)) { a.companyId = remap[a.companyId]; ch = true; } }); if (ch) saveAgreements(ags); } catch (e) {}
