    if (m) { Object.keys(m).forEach(function(k){ const p = m[k]; if (p && typeof p.taxId === 'string') { const dig = p.taxId.replace(/\D/g,''); if (dig.length > 4) { p.taxId = dig.slice(-4); changed = true; } } }); }
    if (changed) saveSettings(s);
